  public getRate(code: string): ITaxRateRecord | undefined {
    return this.rates.get(code);
  }

  public calculateTaxForDistrict(code: string, amountUSD: number, isFood: boolean, isApparel: boolean): number {
    const r = this.getRate(code);
    if (!r) return +(amountUSD * 0.075).toFixed(2);
    if (isFood && r.isFoodExempt) return 0.0;
    if (isApparel && r.isApparelExempt) return 0.0;
    return +(amountUSD * (r.combinedRatePct / 100)).toFixed(2);
  }
